svg.script:
var details = document.getElementById("details");
function s(info) { details.firstChild.nodeValue = info; }
function c() { details.firstChild.nodeValue = " "; }
function search_prompt() {
  var term = prompt("Search regexp:", "");
  if (!term) return;
  var re = new RegExp(term);
  var matched = document.getElementById("matched");
  var totalMatched = 0, totalAll = 0;
  var gs = document.querySelectorAll(".func");
  for (var i = 0; i < gs.length; i++) {
    var rect = gs[i].querySelector("rect");
    var title = gs[i].querySelector("title");
    if (!title) continue;
    var text = title.textContent;
    if (re.test(text)) {
      rect.style.stroke = "#e00"; rect.style.strokeWidth = "1";
      totalMatched++;
    } else {
      rect.style.stroke = ""; rect.style.strokeWidth = "";
    }
    totalAll++;
  }
  matched.firstChild.nodeValue = "matched: " + totalMatched + "/" + totalAll;
}
